{
  "predictors": [
    {
      "name": "Digital Revenue Growth",
      "construction": "Calculate the percentage growth in revenue attributed to digital or online sales from Compustat segment data over the past year.",
      "rationale": "Firms with faster-growing digital revenue streams may have competitive advantages in technology and consumer access.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Environmental Commitment Ratio",
      "construction": "Divide the annual environmental expenditure by total sales from corporate social responsibility reports.",
      "rationale": "Companies investing heavily in environmental sustainability may attract investor interest and reduce regulatory risks.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Employee Satisfaction Index",
      "construction": "Aggregate employee satisfaction scores from surveys or Glassdoor-like platforms and normalize by industry.",
      "rationale": "Firms with happier employees may experience higher productivity, leading to better financial performance.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Customer Retention Rate",
      "construction": "Use company disclosures or industry reports to estimate the percentage of repeat customers over the past year.",
      "rationale": "High customer retention indicates strong customer loyalty and potential for stable revenue streams.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Social Media Engagement",
      "construction": "Average the monthly growth in social media followers or interactions from company-reported data.",
      "rationale": "Active and engaged social media presence may enhance brand strength and market penetration.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Innovation Expenditure Ratio",
      "construction": "Divide the annual research and development expense by total assets from Compustat.",
      "rationale": "Higher expenditure on innovation may indicate future growth prospects through new products or technologies.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Intellectual Property Accumulation",
      "construction": "Count the number of new patents filed in the last year from USPTO data, scaled by total sales.",
      "rationale": "Accumulating intellectual property may provide competitive advantages and drive future profitability.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Management Stability Index",
      "construction": "Ratio of the number of years top executives have been with the company to the industry average.",
      "rationale": "Stable management teams may ensure consistent strategic execution and lower operational risks.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Supplier Diversity Ratio",
      "construction": "Proportion of total purchases from diverse suppliers as reported in corporate sustainability reports.",
      "rationale": "Diversity in suppliers may lead to a more resilient supply chain and innovative sourcing strategies.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Cybersecurity Investment Intensity",
      "construction": "Annual expenditure on cybersecurity as a percentage of total IT budget from company disclosures.",
      "rationale": "Investments in cybersecurity may reduce the risk of costly breaches and enhance data integrity.",
      "higher_returns_for": "high values of the measure"
    }
  ]
}
